package com.shopsphere;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.data.annotation.Id;import org.springframework.data.domain.Sort;import org.springframework.data.mongodb.core.*;import org.springframework.data.mongodb.core.index.*;import org.springframework.data.mongodb.core.mapping.Document;import org.springframework.data.mongodb.core.query.*;import org.springframework.stereotype.Repository;
@Document("products")class ProductDocument{@Id UUID id;@Indexed(unique=true)String sku;String name;@Indexed(unique=true)String slug;String description;@Indexed String brand;@Indexed String category;BigDecimal price;BigDecimal originalPrice;BigDecimal discountPercentage;double rating;long reviewCount;List<String>imageUrls;Map<String,String>specifications;boolean active;Instant createdAt;Instant updatedAt;ProductDocument(){}ProductDocument(Product p){id=p.id();sku=p.sku();name=p.name();slug=p.slug();description=p.description();brand=p.brand();category=p.category();price=p.price();originalPrice=p.originalPrice();discountPercentage=p.discountPercentage();rating=p.rating();reviewCount=p.reviewCount();imageUrls=p.imageUrls();specifications=p.specifications();active=p.active();createdAt=p.createdAt();updatedAt=p.updatedAt();}Product domain(){return new Product(id,sku,name,slug,description,brand,category,price,originalPrice,discountPercentage,rating,reviewCount,imageUrls,specifications,active,createdAt,updatedAt);}}
@Repository class MongoProductRepository implements ProductRepository{private final MongoTemplate mongo;MongoProductRepository(MongoTemplate m){mongo=m;}public Product save(Product p){return mongo.save(new ProductDocument(p)).domain();}public Optional<Product>findById(UUID id){return Optional.ofNullable(mongo.findById(id,ProductDocument.class)).map(ProductDocument::domain);}public Optional<Product>findBySlug(String s){return one(Criteria.where("slug").is(s));}public Optional<Product>findBySku(String s){return one(Criteria.where("sku").is(s));}private Optional<Product>one(Criteria c){return Optional.ofNullable(mongo.findOne(Query.query(c),ProductDocument.class)).map(ProductDocument::domain);}public List<Product>findAll(){return mongo.findAll(ProductDocument.class).stream().map(ProductDocument::domain).toList();}public void delete(UUID id){mongo.remove(Query.query(Criteria.where("_id").is(id)),ProductDocument.class);}public Search search(String q,String category,String brand,BigDecimal min,BigDecimal max,Double rating,String sort,int page,int size){List<Criteria>c=new ArrayList<>();c.add(Criteria.where("active").is(true));if(q!=null&&!q.isBlank()){for(String term:q.trim().split("\\s+")){String pattern=java.util.regex.Pattern.quote(term);c.add(new Criteria().orOperator(Criteria.where("name").regex(pattern,"i"),Criteria.where("description").regex(pattern,"i"),Criteria.where("brand").regex(pattern,"i"),Criteria.where("category").regex(pattern,"i")));}}if(category!=null&&!category.isBlank())c.add(Criteria.where("category").regex("^"+java.util.regex.Pattern.quote(category.trim())+"$","i"));if(brand!=null&&!brand.isBlank())c.add(Criteria.where("brand").regex("^"+java.util.regex.Pattern.quote(brand.trim())+"$","i"));if(min!=null||max!=null){Criteria price=Criteria.where("price");if(min!=null)price.gte(min);if(max!=null)price.lte(max);c.add(price);}if(rating!=null)c.add(Criteria.where("rating").gte(rating));Query query=Query.query(new Criteria().andOperator(c));long total=mongo.count(query,ProductDocument.class);String field=switch(sort==null?"newest":sort){case"price_asc","price_desc"->"price";case"rating"->"rating";default->"createdAt";};Sort.Direction direction=("price_asc".equals(sort))?Sort.Direction.ASC:Sort.Direction.DESC;query.with(Sort.by(direction,field)).skip((long)page*size).limit(size);return new Search(mongo.find(query,ProductDocument.class).stream().map(ProductDocument::domain).toList(),total);}}
